using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class HouseSuccessionTests
{
    static readonly EntityId Home=new("site:kofu"),Owner=new("org:takeda"),Old=new("person:shingen"),Heir=HistoricalHouseholdCatalog.Edition.People.Single().Id;
    static WorldSession Start(bool heir=false,string? policy=null)=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],heir?Heir.Value:Old.Value,42,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:policy??HouseSuccession.Policy));
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void Advance(WorldSession s,long at){while(s.Seconds<at){long before=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>before);}}
    static HouseSuccessionInput Input(WorldSession s,HouseSuccessionAction a,EntityId? original=null)=>new(new("request:house-test/"+s.Revision),a,Owner,a==HouseSuccessionAction.Nominate?Heir:null,original);
    static EntityId Nominate(WorldSession s){var i=Input(s,HouseSuccessionAction.Nominate);Good(s.ManageHouseSuccession(i,s.PlayerControl,s.Revision));return i.Id;}
    static EntityId Succeed(WorldSession s){var id=Nominate(s);Good(s.ManageHouseSuccession(Input(s,HouseSuccessionAction.Confirm,id),s.PlayerControl,s.Revision));Advance(s,s.Seconds+1);return id;}
    [Fact]public void NominationAndConfirmationDoNotChangeHeadBeforeClockBoundary(){var s=Start();var id=Nominate(s);Good(s.ManageHouseSuccession(Input(s,HouseSuccessionAction.Confirm,id),Old,s.Revision));Assert.Equal(Old,HouseSuccession.Head(s.DiagnosticSnapshot(),Owner));Assert.Equal(0,s.Seconds);Advance(s,1);Assert.Equal(Heir,HouseSuccession.Head(s.DiagnosticSnapshot(),Owner));}
    [Fact]public void OfficeChangesWithoutMovingAnyPeopleLandMoneyTroopsOrOriginalScenario(){var s=Start();var a=s.DiagnosticSnapshot();Succeed(s);var b=s.DiagnosticSnapshot();Assert.Equal(ContractJson.Write(a.NewGame),ContractJson.Write(b.NewGame));Assert.Equal(ContractJson.Write(a.Memberships),ContractJson.Write(b.Memberships));Assert.Equal(ContractJson.Write(a.ServiceBonds),ContractJson.Write(b.ServiceBonds));Assert.Equal(ContractJson.Write(a.LandRights),ContractJson.Write(b.LandRights));Assert.Equal(ContractJson.Write(a.Units),ContractJson.Write(b.Units));Assert.Equal(ContractJson.Write(a.ResourceLots),ContractJson.Write(b.ResourceLots));Assert.Contains(b.Offices,o=>o.Subject==Old&&o.Kind=="house-head"&&o.Until==1);Assert.Contains(b.Offices,o=>o.Subject==Heir&&o.Kind=="house-head"&&o.From==1&&o.Until==long.MaxValue);}
    [Fact]public void CurrentAndHistoricalPoliticalAuthorityAreSeparate(){var s=Start(true);long original=s.Revision;Succeed(s);var w=s.DiagnosticSnapshot();Assert.NotNull(FactionStances.ResolveAuthority(w,Old,Owner,0,original));Assert.Null(FactionStances.ResolveAuthority(w,Old,Owner,s.Seconds,s.Revision));Assert.NotNull(FactionStances.ResolveAuthority(w,Heir,Owner,s.Seconds,s.Revision));Assert.Equal(Old,HouseSuccession.Head(w,Owner,0,original));}
    [Fact]public void RefusalNeverCreatesPower(){var s=Start();var w=s.DiagnosticSnapshot();w.Characters=w.Characters.Select(c=>c.Id==Heir?c with{WillObey=false}:c).ToArray();s=new(w);var id=Nominate(s);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseSuccession(Input(s,HouseSuccessionAction.Confirm,id),Old,s.Revision).Code);Assert.Equal(Old,HouseSuccession.Head(s.DiagnosticSnapshot(),Owner));}
    [Fact]public void CancellingPendingChangeKeepsOriginalHead(){var s=Start();var id=Nominate(s);Good(s.ManageHouseSuccession(Input(s,HouseSuccessionAction.Confirm,id),Old,s.Revision));Good(s.ManageHouseSuccession(Input(s,HouseSuccessionAction.Cancel,id),Old,s.Revision));Advance(s,2);Assert.Equal(Old,HouseSuccession.Head(s.DiagnosticSnapshot(),Owner));}
    [Fact]public void AlreadyCompletedOfficeCannotBeRolledBackByCancellation(){var s=Start();var id=Succeed(s);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseSuccession(Input(s,HouseSuccessionAction.Cancel,id),Old,s.Revision).Code);Assert.Equal(Heir,HouseSuccession.Head(s.DiagnosticSnapshot(),Owner));}
    [Fact]public void PublicCallerCannotResolveTheClockEvent(){var s=Start();var id=Nominate(s);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseSuccession(Input(s,HouseSuccessionAction.Resolve,id),Old,s.Revision).Code);}
    [Fact]public void OldPolicyDoesNotAcquireSuccessionByLoading(){var s=Start(policy:CastleAdministration.Policy);Assert.Null(s.DiagnosticSnapshot().Succession);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseSuccession(Input(s,HouseSuccessionAction.Nominate),Old,s.Revision).Code);}
    [Fact]public void ReplayAndConflictAreAtomic(){var s=Start();var i=Input(s,HouseSuccessionAction.Nominate);Good(s.ManageHouseSuccession(i,Old,s.Revision));Assert.Equal(ResultCode.AlreadyAccepted,s.ManageHouseSuccession(i,Old,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.ManageHouseSuccession(i with{Person=Old},Old,s.Revision).Code);}
    [Fact]public void MissingActualOfficeChangeCannotBeForgedInSave(){var s=Start();Succeed(s);var w=s.DiagnosticSnapshot();w.Offices=Start().DiagnosticSnapshot().Offices;Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    static EntityId AgreeSalary(WorldSession s){var id=new EntityId("request:succession-salary");Good(s.ManageSalary(new(id,SalaryAction.Propose,Old,Home,Amount:20),s.PlayerControl,s.Revision));Good(s.ManageSalary(new(new("request:succession-salary-confirm"),SalaryAction.Confirm,Old,Home,id),s.PlayerControl,s.Revision));return id;}
    static EntityId Ack(WorldSession s,EntityId original){var i=Input(s,HouseSuccessionAction.Acknowledge,original);Good(s.ManageHouseSuccession(i,s.PlayerControl,s.Revision));return i.Id;}
    [Fact]public void NewHeadGetsAdministrationBudgetAndOwnMilitaryAuthority(){var s=Start(true);Succeed(s);Assert.True(s.HouseTreasuryView()!.CanSetBudget);Good(s.ManageHouseTreasury(new(new("request:new-head-budget"),TreasuryAction.SetBudget,Home,Amount:500),s.PlayerControl,s.Revision));var a=NewGameMilitaryAuthority.Resolve(s.DiagnosticSnapshot(),Heir,Heir,Owner,Home);Assert.NotNull(a);Assert.Contains(s.DiagnosticSnapshot().Offices,o=>o.Id==a.Office&&o.Subject==Heir);Assert.True(NewGameMilitary.CanRequestOwnAuthority(s.DiagnosticSnapshot()));}
    [Fact]public void RetiredHeadCannotSpendHouseFundsOrDeclareFreshHostility(){var s=Start();Succeed(s);Assert.Null(s.HouseTreasuryView());Assert.Null(FactionStances.ResolveAuthority(s.DiagnosticSnapshot(),Old,Owner,s.Seconds,s.Revision));Assert.Contains("隠居",s.PersonalLifeView()!.Role);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseTreasury(new(new("request:retired-budget"),TreasuryAction.SetBudget,Home,Amount:500),s.PlayerControl,s.Revision).Code);}
    [Fact]public void OldPersonalServiceRemainsWithOriginalPerson(){var s=Start(true);Succeed(s);Assert.True(NewGameService.BoundAt(s.DiagnosticSnapshot(),Old,s.Seconds,s.Revision));Assert.Equal(Old,NewGameService.View(s.DiagnosticSnapshot()).Principal);Assert.Contains("当主",s.PersonalLifeView()!.Role);Assert.DoesNotContain(s.DiagnosticSnapshot().ServiceBonds,b=>b.Subject==Old&&b.Target==Heir);}
    [Fact]public void SameHouseSalaryDebtNeedsExplicitAcknowledgmentAndPaysOnce(){var s=Start(true);var contract=AgreeSalary(s);Advance(s,s.DiagnosticSnapshot().Salary!.Terms.Single().DueAt[0]);Assert.Equal(20,s.SalaryView()!.Contracts.Single().Owed);Succeed(s);var before=s.DiagnosticSnapshot();Assert.Equal(Old,before.Salary!.Terms.Single().Employer);Assert.Equal(Owner,before.Salary.Terms.Single().Owner);Assert.Equal(20,s.SalaryView()!.Contracts.Single().Owed);Assert.Equal(ResultCode.NotAvailable,s.ManageSalary(new(new("request:unacknowledged-debt"),SalaryAction.Prepare,Old,Home,contract,20),s.PlayerControl,s.Revision).Code);Ack(s,contract);Assert.Equal(ContractJson.Write(before.ResourceLots),ContractJson.Write(s.DiagnosticSnapshot().ResourceLots));var prep=new EntityId("request:acknowledged-salary-prep");Good(s.ManageSalary(new(prep,SalaryAction.Prepare,Old,Home,contract,20),s.PlayerControl,s.Revision));Good(s.ManageSalary(new(new("request:acknowledged-salary-receive"),SalaryAction.Receive,Old,Home,contract,Preparation:prep),s.PlayerControl,s.Revision));Assert.Equal(20,s.SalaryView()!.PrivateRice);Assert.Equal(0,s.SalaryView()!.Contracts.Single().Owed);Assert.Equal(ResultCode.NotAvailable,s.ManageSalary(new(new("request:double-salary-receive"),SalaryAction.Receive,Old,Home,contract,Preparation:prep),s.PlayerControl,s.Revision).Code);new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));}
    [Fact]public void RetiredHeadCannotUseOriginalSalaryContractToControlSuccessorsRice(){var s=Start();var id=new EntityId("request:retired-house-salary");Good(s.ManageSalary(new(id,SalaryAction.Propose,Heir,Home,Amount:20),Old,s.Revision));Good(s.ManageSalary(new(new("request:retired-house-salary-confirm"),SalaryAction.Confirm,Heir,Home,id),Old,s.Revision));Advance(s,s.DiagnosticSnapshot().Salary!.Terms.Single().DueAt[0]);Succeed(s);Assert.Equal(ResultCode.NotAvailable,s.ManageSalary(new(new("request:retired-house-salary-steal"),SalaryAction.Prepare,Heir,Home,id,20),Old,s.Revision).Code);Assert.Equal(20,s.SalaryView()!.Contracts.Single().Owed);}

    static void Move(WorldSession s,string node){Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:house-trip/"+s.Revision,node),s.Revision));Advance(s,s.Seconds+2);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==s.PlayerControl).Legs[^1].EndAt+1);}
    [Theory][InlineData(false)][InlineData(true)]public void OutstandingFreightKeepsOriginalOwnerAndNeedsIndividualAcknowledgment(bool playerHeir){var s=Start(playerHeir);var job=new EntityId("request:succession-freight");Good(s.ManageHouseFreight(new(job,HouseFreightAction.Dispatch,Home:Home,Source:new("site:castle"),Commodity:"wood",Quantity:10,Advance:200),s.PlayerControl,s.Revision));Move(s,"castle");Good(s.ManageHouseFreight(new(new("request:succession-freight-buy"),HouseFreightAction.Buy,job),s.PlayerControl,s.Revision));Move(s,"kofu");var original=s.HouseFreightView()!.Jobs.Single().Terms;Succeed(s);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseFreight(new(new("request:unacknowledged-freight"),HouseFreightAction.Receive,job),s.PlayerControl,s.Revision).Code);var acknowledged=Ack(s,job);var before=s.DiagnosticSnapshot();long wood=before.Materials!.Houses.Single(h=>h.Site==Home).Wood;Good(s.ManageHouseFreight(new(new("request:acknowledged-freight"),HouseFreightAction.Receive,job),s.PlayerControl,s.Revision));var j=s.HouseFreightView()!.Jobs.Single();Assert.Equal(original,j.Terms);Assert.Equal(Old,j.Terms.Principal);Assert.Equal(Owner,j.Receipt!.Owner);Assert.Equal(Heir,j.Receipt.Receiver);Assert.Equal(acknowledged,j.Receipt.Grant);Assert.Equal(10,j.Receipt.Cargo);Assert.Equal(wood+10,s.DiagnosticSnapshot().Materials!.Houses.Single(h=>h.Site==Home).Wood);Assert.Equal(HouseFreightPhase.Completed,j.Phase);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseFreight(new(new("request:double-freight"),HouseFreightAction.Receive,job),s.PlayerControl,s.Revision).Code);new WorldSession(ContractJson.Copy(s.DiagnosticSnapshot()));}
    [Fact]public void GateOccupationAtTheScheduledBoundaryHoldsTheRemainingHeadChange(){var s=CastleHandoverTests.Start(policy:HouseSuccession.Policy);var id=Nominate(s);Good(s.ManageHouseSuccession(Input(s,HouseSuccessionAction.Confirm,id),Old,s.Revision));var gate=new EntityId("request:house-occupation");Good(s.ManageCastle(new(gate,CastleAction.Offer,Home,RecipientOwner:new("org:oda")),Old,s.Revision));foreach(var a in new[]{CastleAction.Confirm,CastleAction.Gate})Good(s.ManageCastle(new(new("request:house-occupation/"+a),a,Home,gate),Old,s.Revision));Advance(s,s.Seconds+1);Assert.Equal(Old,HouseSuccession.Head(s.DiagnosticSnapshot(),Owner));Assert.Equal("occupation-hold",HouseSuccession.Jobs(s.DiagnosticSnapshot()).Single().Resolution!.Outcome);Assert.NotNull(CastleHandover.Jobs(s.DiagnosticSnapshot()).Single().Gate);}
    [Fact]public void ExpiredAgreementCannotChangeTheHead(){var s=Start();var id=Nominate(s);Advance(s,86401);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseSuccession(Input(s,HouseSuccessionAction.Confirm,id),Old,s.Revision).Code);Assert.Equal(Old,HouseSuccession.Head(s.DiagnosticSnapshot(),Owner));}
    [Fact]public void DepartedHeirCannotConfirmUsingTheEarlierMeeting(){var s=Start(true);var id=Nominate(s);Move(s,"castle");Assert.Equal(ResultCode.NotAvailable,s.ManageHouseSuccession(Input(s,HouseSuccessionAction.Confirm,id),Heir,s.Revision).Code);Assert.Equal(Old,HouseSuccession.Head(s.DiagnosticSnapshot(),Owner));}
    [Fact]public void AcknowledgmentCannotCreateDebtOrAcceptAnotherOwnersOriginal(){var s=Start(true);Succeed(s);Assert.Equal(ResultCode.NotAvailable,s.ManageHouseSuccession(Input(s,HouseSuccessionAction.Acknowledge,new("request:nonexistent-debt")),Heir,s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().Salary!.Terms);Assert.Empty(s.DiagnosticSnapshot().HouseFreight!.Entries);}

}
